<script>
  let { savingPlan = $bindable(null) } = $props();
  let debtRange = $state(50000); let reductionRate = $state(40);
  const debtRanges=[['$20,000 - $40,000',30000],['$41,000 - $99,000',70000],['$100,000 - $249,999',150000],['Más de $250,000',250000]];
  let estimated = $derived(Math.round(Number(debtRange) * (1 - Number(reductionRate) / 100)));
  function sendPlan(){ savingPlan={debtRange:Number(debtRange),reductionRate:Number(reductionRate),estimated}; const form=document.getElementById('formulario-captacion'); if(form) form.scrollIntoView({behavior:'smooth'}); else window.location.href=`${import.meta.env.BASE_URL}#formulario-captacion`; }
</script>
<section id="simulador" class="py-16 sm:py-20"><div class="mx-auto grid max-w-7xl gap-8 px-4 sm:px-6 lg:grid-cols-[.85fr_1.15fr] lg:px-8"><div><p class="eyebrow">Calculadora orientativa</p><h2 class="mt-3 text-3xl font-extrabold sm:text-4xl">Simula cuánto podría bajar tu deuda</h2><p class="muted mt-4 leading-relaxed">Selecciona un rango y un escenario ilustrativo. No representa una propuesta, descuento garantizado ni resultado definitivo.</p></div><div class="card rounded-2xl p-6 sm:p-8"><div class="grid gap-6 sm:grid-cols-2"><label class="font-semibold">¿Cuál es tu deuda aproximada?<select class="field mt-2" bind:value={debtRange}><option value="" disabled>Rango de deuda</option>{#each debtRanges as range}<option value={range[1]}>{range[0]}</option>{/each}</select></label><label class="font-semibold">Escenario ilustrativo<select class="field mt-2" bind:value={reductionRate}><option value="30">30% de reducción</option><option value="40">40% de reducción</option><option value="50">50% de reducción</option></select></label></div><div class="mt-6 rounded-xl p-5" style="background:var(--brand-soft)"><p class="muted text-sm">Referencia de saldo restante</p><p class="mt-1 text-3xl font-extrabold" style="color:var(--brand)">${estimated.toLocaleString('es-MX')} MXN</p><p class="muted mt-2 text-xs leading-relaxed">La alternativa real depende de tu caso, la institución y la negociación. Un asesor te explicará las condiciones antes de cualquier decisión.</p></div><button class="btn-primary focus-ring mt-6 rounded-lg px-5 py-3 font-bold" onclick={sendPlan}><span class="button-label">Usar esta referencia al revisar mi caso</span></button></div></div></section>
